/bin/zsh -lc "python - <<'PY'
import json
for f in ['policy.json','coordination.json','source.json']:
 d=json.load(open(f))
 print(f, type(d).__name__)
 if f"'!='"'source.json': print(json.dumps(d,ensure_ascii=False,indent=2))
 else:
  print('keys',list(d) if isinstance(d,dict) else 'list')
  a=d if isinstance(d,list) else d.get('articles',d.get('sources',[]))
  print('articles',len(a))
  for i,x in enumerate(a): print(i,[(k,x[k]) for k in ['code_id','source_id','number'] if k in x], 'xml length',len(x.get('source_xml','')), 'notes length',len(str(x.get('source_notes_xml',''))))
PY"

